<script setup lang="ts">
import {ref} from 'vue'
import {type AIRecord} from './helpers'
const props=defineProps<{content:AIRecord;disabled?:boolean}>()
const emit=defineEmits<{change:[];evidence:[path:string]}>()
const tab=ref('identity')
function parser(){props.content.parserSpec={dslVersion:'1.0',inputKind:'RAW',length:4,fields:[]};tab.value='parser';emit('change')}
function addField(){props.content.parserSpec.fields.push({name:'',offset:0,type:'uint8'});emit('change')}
function changeType(f:AIRecord){if(['uint16','int16','uint32','int32'].includes(f.type))f.endian=f.endian||'little';else delete f.endian;if(f.type==='bytes')f.length=f.length||1;else delete f.length;emit('change')}
function connect(){props.content.connectionSpec={serviceUuid:'',characteristicUuid:'',security:'UNENCRYPTED',operation:'GATT_READ'};tab.value='connection';emit('change')}
function mapping(){props.content.mappingSpec={fields:[]};tab.value='mapping';emit('change')}
function number(f:AIRecord,key:string,value:any){if(value===undefined||value===null||value==='')delete f[key];else f[key]=Number(value);emit('change')}
function text(f:AIRecord,key:string,value:string){if(value.trim())f[key]=value.trim();else delete f[key];emit('change')}
function removePart(part:string){props.content[part]=null;emit('change')}
defineExpose({showTab:(name:string)=>tab.value=name})
</script>
<template><el-form label-position="top" :disabled="disabled" @input="emit('change')">
<el-tabs v-model="tab">
<el-tab-pane label="型号" name="identity"><el-form-item label="型号或接口名称" required><el-input v-model="content.modelName" placeholder="从资料中识别的具体型号"/></el-form-item><el-form-item label="厂家"><el-input v-model="content.manufacturer"/></el-form-item><el-form-item label="适用固件版本"><el-input v-model="content.firmwareRange" placeholder="按文档填写；未知时保留空白"/></el-form-item><p class="muted">真实蓝牙地址、网关与现场分组在应用时选择，不从说明书中的示例自动登记。</p><div class="capability-actions"><el-button v-if="!content.parserSpec" @click="parser">添加解析方案</el-button><el-button v-if="!content.connectionSpec" @click="connect">添加 GATT 方案</el-button><el-button v-if="!content.mappingSpec" @click="mapping">添加字段映射</el-button></div></el-tab-pane>
<el-tab-pane label="解析字段" name="parser"><template v-if="content.parserSpec"><div class="editor-row"><el-form-item label="输入报文"><el-select v-model="content.parserSpec.inputKind" @change="emit('change')"><el-option label="完整原始负载" value="RAW"/><el-option label="BLE 广播结构" value="BLE_AD"/><el-option label="GATT 特征值" value="GATT_VALUE"/></el-select></el-form-item><el-form-item v-if="content.parserSpec.length!==undefined" label="总长度 字节"><el-input-number v-model="content.parserSpec.length" :min="1" :max="65536" @change="emit('change')"/></el-form-item></div>
<p v-if="content.parserSpec.source" class="notice">已配置广播子区段选择器。字段偏移相对于选择后的数据区域；详细选择条件可在高级结构中审阅。</p>
<div v-for="(f,i) in content.parserSpec.fields" :key="i" class="field-card" :id="'protocol-field-'+i"><div class="field-title"><strong>字段 {{Number(i)+1}}</strong><div><el-button link @click="emit('evidence','parserSpec.fields.'+i)">查看依据</el-button><el-button link type="danger" @click="content.parserSpec.fields.splice(i,1);emit('change')">移除</el-button></div></div>
<div class="editor-row"><el-form-item label="字段名称" required><el-input v-model="f.name" placeholder="temperature"/></el-form-item><el-form-item label="起始偏移 字节" required><el-input-number v-model="f.offset" :min="0" :max="65535" @change="emit('change')"/></el-form-item><el-form-item label="数据类型" required><el-select v-model="f.type" @change="changeType(f)"><el-option v-for="t in ['uint8','int8','uint16','int16','uint32','int32','bytes']" :key="t" :label="t" :value="t"/></el-select></el-form-item><el-form-item v-if="['uint16','int16','uint32','int32'].includes(f.type)" label="字节序"><el-select v-model="f.endian" @change="emit('change')"><el-option label="小端 little" value="little"/><el-option label="大端 big" value="big"/></el-select></el-form-item><el-form-item v-if="f.type==='bytes'" label="字节长度"><el-input-number v-model="f.length" :min="1" :max="65536" @change="emit('change')"/></el-form-item><el-form-item label="倍率"><el-input-number :model-value="f.scale" :controls="false" placeholder="默认 1" @update:model-value="v=>number(f,'scale',v)"/></el-form-item><el-form-item label="单位"><el-input :model-value="f.unit||''" placeholder="Cel / %" @update:model-value="v=>text(f,'unit',v)"/></el-form-item></div>
<el-collapse><el-collapse-item title="偏置 有效范围与位域"><div class="editor-row"><el-form-item v-for="k in [{key:'bias',label:'偏置'},{key:'min',label:'最小输出值'},{key:'max',label:'最大输出值'},{key:'bitOffset',label:'起始位'},{key:'bitLength',label:'位宽'}]" :key="k.key" :label="k.label"><el-input-number :model-value="f[k.key]" :controls="false" @update:model-value="v=>number(f,k.key,v)"/></el-form-item></div></el-collapse-item></el-collapse></div>
<div class="toolbar"><el-button @click="addField" :disabled="content.parserSpec.fields.length>=128">添加字段</el-button><el-button link type="danger" @click="removePart('parserSpec')">移除解析方案</el-button></div><p class="muted">CRC、枚举、广播选择器和有界变长可在高级结构中配置；服务端只接受受限 DSL，不执行脚本。</p></template><el-empty v-else description="此草稿尚无解析方案"><el-button @click="parser">添加解析方案</el-button></el-empty></el-tab-pane>
<el-tab-pane label="GATT" name="connection"><template v-if="content.connectionSpec"><el-form-item label="服务 UUID" required><el-input v-model="content.connectionSpec.serviceUuid" placeholder="180f 或完整 UUID"/></el-form-item><el-form-item label="特征 UUID" required><el-input v-model="content.connectionSpec.characteristicUuid" placeholder="2a19 或完整 UUID"/></el-form-item><div class="editor-row"><el-form-item label="操作"><el-select v-model="content.connectionSpec.operation" @change="emit('change')"><el-option label="读取" value="GATT_READ"/><el-option label="写入" value="GATT_WRITE"/><el-option label="订阅" value="GATT_SUBSCRIBE"/></el-select></el-form-item><el-form-item label="安全要求"><el-select v-model="content.connectionSpec.security" @change="emit('change')"><el-option label="不要求加密" value="UNENCRYPTED"/><el-option label="使用已有绑定加密" value="BONDED_ENCRYPTED"/></el-select></el-form-item></div><el-form-item v-if="content.connectionSpec.operation==='GATT_SUBSCRIBE'" label="通知方式"><el-select v-model="content.connectionSpec.mode" @change="emit('change')"><el-option label="NOTIFY" value="NOTIFY"/><el-option label="INDICATE" value="INDICATE"/></el-select></el-form-item><template v-if="content.connectionSpec.operation==='GATT_WRITE'"><el-form-item label="写入值 Base64"><el-input v-model="content.connectionSpec.valueBase64" type="textarea" placeholder="只记录文档定义的操作，不会立即发送"/></el-form-item><el-form-item label="验证方式"><el-select v-model="content.connectionSpec.verification" @change="emit('change')"><el-option label="读取回验" value="READBACK"/><el-option label="仅 ATT 响应" value="NONE"/></el-select></el-form-item></template><p class="notice">这里只定义接口模板。实际连接和特征句柄来自现场；配对码、动态地址与厂商握手不由模型自动完成。</p><el-button link @click="emit('evidence','connectionSpec')">查看接口依据</el-button><el-button link type="danger" @click="removePart('connectionSpec')">移除 GATT 方案</el-button></template><el-empty v-else description="此草稿尚无连接方案"><el-button @click="connect">添加 GATT 方案</el-button></el-empty></el-tab-pane>
<el-tab-pane label="客户映射" name="mapping"><template v-if="content.mappingSpec"><p class="muted">仅映射 data 内的顶层字段；接收地址、认证和业务确认在转发目标页面核对。</p><div v-for="(f,i) in content.mappingSpec.fields" :key="i" class="field-card"><div class="editor-row"><el-form-item label="源字段"><el-input v-model="f.source"/></el-form-item><el-form-item label="目标字段"><el-input v-model="f.target"/></el-form-item><el-form-item label="倍率"><el-input-number :model-value="f.scale" :controls="false" @update:model-value="v=>number(f,'scale',v)"/></el-form-item><el-form-item label="偏移"><el-input-number :model-value="f.offset" :controls="false" @update:model-value="v=>number(f,'offset',v)"/></el-form-item><el-form-item label="单位"><el-input :model-value="f.unit||''" @update:model-value="v=>text(f,'unit',v)"/></el-form-item></div><el-button link type="danger" @click="content.mappingSpec.fields.splice(i,1);emit('change')">移除此映射</el-button></div><el-button @click="content.mappingSpec.fields.push({source:'',target:''});emit('change')">添加映射字段</el-button><el-button link @click="emit('evidence','mappingSpec')">查看映射依据</el-button><el-button link type="danger" @click="removePart('mappingSpec')">移除映射方案</el-button></template><el-empty v-else description="此草稿尚无客户字段映射"><el-button @click="mapping">添加字段映射</el-button></el-empty></el-tab-pane>
</el-tabs></el-form></template>
<style scoped>.editor-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 12px}.field-card{border:1px solid #dfe7eb;border-radius:7px;padding:14px;margin:14px 0;background:#fafcfd}.field-title{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px;font-size:13px}.field-title>div{display:flex;flex-wrap:wrap}.el-form :deep(.el-select),.el-form :deep(.el-input-number){width:100%}.capability-actions{display:flex;flex-wrap:wrap;gap:9px}.capability-actions .el-button{margin:0}.notice{margin-top:12px}.toolbar{margin-top:16px}@media(max-width:450px){.editor-row{grid-template-columns:1fr}.field-title{flex-wrap:wrap}}</style>
